import itertools, sys, json
L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}
# precompute all valid triples (a,b,c) with a<b and a+b=c
triples = [(a,b,a+b) for a,b in itertools.combinations(L,2) if a+b in L]
# build adjacency for each number to triples containing it
from collections import defaultdict
adj = defaultdict(list)
for t in triples:
    for x in t:
        adj[x].append(t)

solution = []
used = set()

sys.setrecursionlimit(10000)

def backtrack():
    if len(solution) == 15:
        return True
    # pick unused number with fewest candidate triples
    candidates = [(len([t for t in adj[x] if all(y not in used for y in t)]), x) for x in L if x not in used]
    if not candidates:
        return False
    _, x = min(candidates)
    for t in adj[x]:
        if all(y not in used for y in t):
            solution.append(t)
            used.update(t)
            if backtrack():
                return True
            solution.pop()
            used.difference_update(t)
    return False

found = backtrack()
if found:
    result = {"triples": solution}
else:
    result = None
print('WITNESS: ' + json.dumps({"polarity": "positive" if found else "negative", "evidence": {"path": "execution://witness"}, "data": result}))
